// 1. Dùng Type cho Union Options (Discriminated Union)
export type ButtonVariant = 'primary' | 'secondary' | 'outline';
export type ButtonSize = 'sm' | 'md' | 'lg';

// 2. Dùng Interface cho Props chính (Extensible)
export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  isLoading?: boolean;
}

// 3. Component chuẩn Enterprise (Tên súc tích, không thêm tiền tố 'Custom' thừa)
export function Button({
  variant = 'primary',
  size = 'md',
  isLoading = false,
  children,
  onClick,
  ...restProps
}: ButtonProps) {
  const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (isLoading) return;
    onClick?.(e);
  };

  return (
    <button onClick={handleClick} disabled={isLoading} {...restProps}>
      {isLoading ? <span>Loading...</span> : children}
    </button>
  );
}

