// 1. app/dashboard/error.tsx (Next.js 16 Client Error Boundary)
'use client';
import { useEffect } from 'react';

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Gửi log lỗi lên Sentry / LogRocket
    console.error('Unhandled Route Error:', error);
  }, [error]);

  return (
    <div className="p-6 rounded-xl border border-red-500/30 bg-red-500/10 space-y-4">
      <h2 className="text-sm font-bold text-red-400">⚠️ Đã xảy ra lỗi ở phân hệ này!</h2>
      <p className="text-xs text-muted-foreground">{error.message}</p>
      <button onClick={() => reset()} className="px-3 py-1.5 bg-red-500 text-white text-xs rounded-lg">
        Thử khôi phục (Reset)
      </button>
    </div>
  );
}
